 ('Oedo','SaturdayHoliday',ARRAY['1001A','1002A','1003A','1004A','1005A','1006A','1007A','1008A','1009A','1010A','1017B','1018B','1019B','1020B','1021B','1022B','1023B','1024B','1025B','1026B','1101B','1102B','1103B','1104B','1111A','1112A','1113A','1114A','1115A','1116A','1117A','1118A','1119A','1120A','1127B','1128B','1129B','1130B','1131B','1132B','1205B','1206B','1207B','1208B','1209B','1210B','1211B','1212B','1213B','1214B','1221A','1222A','1223A','1224A','1225A','1226A','1227A','1228A','1229A','1230A','1301A','1302A','1303A','1304A','1305A','1306A','1307A','1308A','1315B','1316B','1317B','1318B','1319B','1320B','1321B','1322B','1323B','1324B','1331A','1332A','1401B','1402B','1409A','1410A','1411A','1412A','1413A','1414A','1415A','1416A','1417A','1418A','1425B','1426B','1427B','1428B','1429B','1430B','1431B','1432B','1503B','1504B','1505B','1506B','1507B','1508B','1509B','1510B','1511B','1512B','1519A','1520A','1521A','1522A','1523A','1524A','1525A','1526A','1527A','1528A','1601A','1602A','1603A','1604A','1605A','1606A','1613B','1614B','1615B','1616B','1617B','1618B','1619B','1620B','1621B','1622B','1629A','1630A','1631A','1632A','1707A','1708A','1709A','1710A','1711A','1712A','1713A','1714A','1715A','1716A','1723B','1724B','1725B','1726B','1727B','1728B','1729B','1730B','1731B','1732B','1801B','1802B','1803B','1804B','1805B','1806B','1807B','1808B','1809B','1810B','1817A','1818A','1819A','1820A','1821A','1822A','1823A','1824A','1825A','1826A','1827A','1901A','1902A','1903A','1904A','1911B','1912B','1913B','1914B','1915B','1916B','1917B','1918B','1919B','1920B','1928A','1929A','1930A','1931A','1932A','2005A','2006A','2007A','2008A','2009A','2010A','2011A','2012A','2014A','2015A','2022B','2023B','2024B','2025B','2026B','2027B','2028B','2029B','2031B','2101B','2102B','2103B','2105B','2106B','2108B','2116A','2117A','2118A','2119A','2120A','2122A','2123A','2124A','2125A','2132B','2201A','2202A','2209B','2211B','2212B','2214B','2215B','2216B','2217B','2218B','2226A','2227A','2229A','2231A','2232A','2303A','2305A','2306A','2308A','2311A','2319B','2322B','2324B','2325B','2326B','2401B','2415A','2417A','2429B','2432B','501B','502B','503B','504A','504B','506A','506B','508A','510A','512A','514A','516A','518A','520A','522A','522B','524A','524B','527B','528B','529B','530B','531B','601A','605B','607B','608B','609B','610B','611B','612B','613B','614B','616B','617A','617B','618B','619A','619B','621A','623A','625A','626A','627A','628A','629A','630A','631A','632A','641A','642A','644A','702A','703A','704A','705A','706A','707A','708A','709A','710A','711A','712A','713A','715B','720B','721B','722B','723B','724B','725B','726B','727B','728B','729B','743A','744B','745A','801B','802B','803B','804B','805B','806B','814A','815A','816A','817A','818A','819A','820A','821A','822A','823A','830B','831B','832B','841B','842B','843B','845B','907B','908B','909B','910B','911B','912B','913B','914B','915B','916B','924A','925A','926A','927A','928A','929A','930A','931A','932A','944A','945A']::text[])
), exact AS (
 SELECT DISTINCT r.line_key,r.cal,n.number FROM roster r CROSS JOIN LATERAL unnest(r.numbers) n(number)
), current_mita AS (
 SELECT DISTINCT m.line_key,replace(m.calendar_urn,'odpt.Calendar:','') cal,m.train_number number
 FROM public.manual_timetable_templates m WHERE m.line_key='Mita' AND m.train_number ~ '^[0-9]{3,4}T$'
), mita_diff AS (
 SELECT coalesce(e.cal,m.cal) cal,count(*) FILTER(WHERE e.number IS NULL) sql_only,
 count(*) FILTER(WHERE m.number IS NULL) roster_only,count(*) FILTER(WHERE e.number IS NOT NULL AND m.number IS NOT NULL) shared
 FROM (SELECT * FROM exact WHERE line_key='Mita') e FULL JOIN current_mita m USING(line_key,cal,number)
 GROUP BY 1
), numbers AS (
 SELECT DISTINCT line_key,number,substring(number from '[0-9]+')::int num,substring(number from '[A-Z]+$') suffix FROM exact
), range_matches AS (
 SELECT n.line_key,n.number,count(DISTINCT p.png_reference) png_count
 FROM numbers n LEFT JOIN public.published_train_png_number_ranges p
 ON p.edition='2611' AND p.line_key=n.line_key AND p.suffix=n.suffix AND n.num BETWEEN p.min_number AND p.max_number
 GROUP BY 1,2
), summary AS (
 SELECT n.line_key,n.suffix,count(*) exact_numbers,count(*) FILTER(WHERE r.png_count=1) one_png,
 count(*) FILTER(WHERE r.png_count>1) conflicting_png,count(*) FILTER(WHERE r.png_count=0) no_png
 FROM numbers n JOIN range_matches r USING(line_key,number) GROUP BY 1,2
), asakusa_extra AS (
 SELECT count(*) extra FROM public.published_train_png_number_ranges p CROSS JOIN LATERAL generate_series(p.min_number,p.max_number) g(num)
 WHERE p.edition='2611' AND p.line_key='Asakusa' AND NOT EXISTS(
 SELECT 1 FROM numbers n WHERE n.line_key=p.line_key AND n.suffix=p.suffix AND n.num=g.num)
), source_templates AS (
 SELECT line_key,count(*) templates,count(distinct train_number) distinct_numbers,count(*) FILTER(WHERE source_revision_date IS NOT NULL) dated,
 count(*) FILTER(WHERE train_number ~ '^[0-9]{3,4}[A-Z]$') simple_suffixed
 FROM public.manual_timetable_templates WHERE line_key IN ('Mita','Asakusa','Shinjuku','Oedo','TokyuMeguro','SotetsuShin-Yokohama','KeioShin') GROUP BY 1
)
SELECT jsonb_build_object(
 'roster_vs_sql_mita',(SELECT jsonb_agg(to_jsonb(d) ORDER BY cal) FROM mita_diff d),
 'reference_inventory',(SELECT jsonb_agg(to_jsonb(s) ORDER BY line_key,suffix) FROM summary s),
 'asakusa_extra_numeric_keys',(SELECT extra FROM asakusa_extra),
 'source_template_inventory',(SELECT jsonb_agg(to_jsonb(t) ORDER BY line_key) FROM source_templates t)
) audit;
